/* DebtVerge self-audit. Run in the SQL editor. Every line must say OK. Re-run after any schema change. */
with allow_anon as (select unnest(array['dv_get_signing_request','dv_sign_request','get_link_payment_state','get_payment_link','submit_change_request']) n)
select 'F1 tables without RLS' k, coalesce(string_agg(c.relname, ', '),'OK') v from pg_class c where c.relnamespace='public'::regnamespace and c.relkind in ('r','p') and not c.relrowsecurity
union all select 'F2 soft-delete tables missing live-row policy', coalesce(string_agg(t.event_object_table, ', '),'OK') from (select distinct event_object_table from information_schema.triggers where trigger_name='trg_soft_delete') t where not exists (select 1 from pg_policies p where p.tablename=t.event_object_table and p.policyname='dv_r_live_sel')
union all select 'F3 functions with mutable search_path', coalesce(string_agg(p.proname, ', '),'OK') from pg_proc p where p.pronamespace='public'::regnamespace and p.prokind='f' and not exists (select 1 from unnest(coalesce(p.proconfig,'{}')) c where c like 'search_path=%') and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')
union all select 'F4 unexpected anon-executable functions', coalesce(string_agg(p.proname, ', '),'OK') from pg_proc p where p.pronamespace='public'::regnamespace and has_function_privilege('anon', p.oid, 'execute') and p.proname not in (select n from allow_anon) and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')
union all select 'F5 anon table grants left', coalesce(string_agg(distinct table_name, ', '),'OK') from information_schema.role_table_grants where table_schema='public' and grantee='anon'
union all select 'F6 audit log changeable', case when has_table_privilege('authenticated','debt_audit_log','UPDATE') or has_table_privilege('authenticated','debt_audit_log','DELETE') or has_table_privilege('authenticated','debt_audit_log','TRUNCATE') or has_table_privilege('service_role','debt_audit_log','UPDATE') or has_table_privilege('service_role','debt_audit_log','DELETE') then 'FOUND' else 'OK' end
union all select 'F7 audit-log guard triggers', case when (select count(distinct tgname) from pg_trigger where tgrelid='public.debt_audit_log'::regclass and not tgisinternal)=3 then 'OK' else 'MISSING' end
union all select 'F8 case tables lacking audit trigger', coalesce(string_agg(c.relname, ', '),'OK') from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='r' and (c.relname like 'debt\_%' or exists (select 1 from pg_attribute a where a.attrelid=c.oid and a.attname='case_id')) and c.relname not in ('debt_audit_log','case_access_log','cashier_audit_logs','payment_reconciliation_log','comms_outbox') and not exists (select 1 from information_schema.triggers t where t.event_object_table=c.relname and t.trigger_name='trg_audit_row')
union all select 'F9 case tables lacking delete guard', coalesce(string_agg(c.relname, ', '),'OK') from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='r' and (c.relname like 'debt\_%' or exists (select 1 from pg_attribute a where a.attrelid=c.oid and a.attname='case_id')) and c.relname not in ('debt_audit_log','case_access_log','cashier_audit_logs','payment_reconciliation_log') and not exists (select 1 from information_schema.triggers t where t.event_object_table=c.relname and t.trigger_name in ('trg_soft_delete','trg_no_delete'))
union all select 'F10 functions reading cases/payments without deleted_at', coalesce(string_agg(p.proname, ', '),'OK') from pg_proc p where p.pronamespace='public'::regnamespace and p.prokind='f' and p.prosrc ~* '(from|join)\s+(debt_payments|debt_creditors|debt_cases)\M' and p.prosrc !~* 'deleted_at' and p.proname not in ('dv_audit_row','dv_audit_stamp','dv_soft_delete','dv_get_signing_request','get_payment_link','get_link_payment_state','submit_change_request','dv_sign_request','dv_log_complaint','dv_is_manager','dv_is_org_member')
union all select 'F11 TRUNCATE/TRIGGER/REFERENCES left', coalesce(string_agg(distinct table_name, ', '),'OK') from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated') and privilege_type in ('TRUNCATE','TRIGGER','REFERENCES')
union all select 'F12 public buckets', coalesce(string_agg(id, ', '),'OK') from storage.buckets where public
union all select 'F13 one-open-run index', case when exists (select 1 from pg_indexes where indexname='disbursement_runs_one_open_per_case') then 'OK' else 'MISSING' end
union all select 'F14 open write policies unguarded', coalesce(string_agg(distinct p.tablename, ', '),'OK') from pg_policies p where p.schemaname='public' and p.permissive='PERMISSIVE' and p.cmd in ('INSERT','UPDATE','DELETE','ALL') and (p.qual='true' or p.with_check='true') and not exists (select 1 from pg_policies r where r.schemaname='public' and r.tablename=p.tablename and r.permissive='RESTRICTIVE' and (r.cmd=p.cmd or r.cmd='ALL' or p.cmd='ALL'))
union all select 'F15 open select on org/case tables unguarded', coalesce(string_agg(distinct p.tablename, ', '),'OK') from pg_policies p where p.schemaname='public' and p.cmd in ('SELECT','ALL') and p.permissive='PERMISSIVE' and p.qual='true' and exists (select 1 from pg_attribute a where a.attrelid=('public.'||p.tablename)::regclass and a.attname in ('organization_id','case_id','user_id')) and not exists (select 1 from pg_policies r where r.schemaname='public' and r.tablename=p.tablename and r.permissive='RESTRICTIVE' and r.cmd in ('SELECT','ALL'))
union all select 'F16 definer fns without pinned path', coalesce(string_agg(p.proname, ', '),'OK') from pg_proc p where p.pronamespace='public'::regnamespace and p.prosecdef and not exists (select 1 from unnest(coalesce(p.proconfig,'{}')) c where c like 'search_path=%')
union all select 'F17 internal fns executable by api roles', coalesce(string_agg(p.proname, ', '),'OK') from pg_proc p where p.pronamespace='public'::regnamespace and (has_function_privilege('authenticated',p.oid,'execute') or has_function_privilege('anon',p.oid,'execute')) and p.proname in ('dv_audit_row','dv_audit_stamp','dv_audit_immutable','dv_soft_delete','dv_no_delete','claim_next_background_job','update_job_progress','requeue_stale_jobs','seed_debtverge_roles','dv_queue_missed_payment_chasers','dv_queue_annual_reviews');
